from pathlib import Path
from statistics import NormalDist
v3=json.loads(Path('\\''generations/sgen013/screen_v3.json'\\'').read_text())
v4=json.loads(Path('\\''generations/sgen013/screen_v4.json'\\'').read_text())
def diff(a,b,p='\\'''\\''):
    if isinstance(a,dict) and isinstance(b,dict):
        for k in sorted(a.keys()|b.keys()):
            if k not in a or k not in b: print(p+'\\''/'\\''+k, repr(a.get(k)), '\\''=>'\\'', repr(b.get(k)))
            else: diff(a[k],b[k],p+'\\''/'\\''+k)
    elif a"'!=b: print(p, repr(a), '"'\\''=>'\\'', repr(b))
diff(v3,v4)
for k in ('\\''population'\\'','\\''coverage'\\'','\\''endpoint_qualification'\\'','\\''selected_components'\\'','\\''selected_endpoint_diagnostic_candidate'\\'','\\''dependence'\\'','\\''variable_registration'\\'','\\''cohort_record'\\''):
    if k=='\\''endpoint_qualification'\\'':
        q=v4[k]
        print(k,{x:v for x,v in q.items() if x"'!='"'\\''disqualifications'\\''},'\\''exclusions='\\'',len(q['\\''disqualifications'\\'']))
    else: print(k,v4[k])
z=NormalDist().inv_cdf(.975)+NormalDist().inv_cdf(.8)
print('\\''min_n_by_p_cov'\\'',{p:next(n for n in range(p+4,1000) if math.tanh(z/math.sqrt(n-3-p))<=.146) for p in (1,2,3,10)})
'"

